"""Backend JSON API for TaskDesk."""

from flask import Blueprint, current_app, jsonify, request
from sqlalchemy import select

from .models import Task, VALID_STATUSES
from . import get_session

api_bp = Blueprint("api", __name__, url_prefix="/api")

def _session():
    return get_session(current_app._get_current_object())

@api_bp.get("/tasks")
def list_tasks():
    q = (request.args.get("q") or "").strip()
    with _session() as s:
        if q:
            tasks = Task.search(s, q)
        else:
            tasks = s.scalars(select(Task).order_by(Task.id)).all()
    return jsonify([t.to_dict() for t in tasks])

@api_bp.get("/tasks/<int:task_id>")
def get_task(task_id):
    with _session() as s:
        task = s.get(Task, task_id)
        if task is None:
            return jsonify({"error": "task not found"}), 404
        return jsonify(task.to_dict())

@api_bp.post("/tasks")
def create_task():
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    description = (data.get("description") or "").strip()
    status = data.get("status") or "open"
    if status not in VALID_STATUSES:
        return jsonify({"error": f"status must be one of {list(VALID_STATUSES)}"}), 400
    with _session() as s:
        task = Task(title=title, description=description, status=status)
        s.add(task)
        s.commit()
        return jsonify(task.to_dict()), 201

